export const skillById = (id: number): CombatSkillContent | undefined => COMBAT_SKILLS[id]

export interface SummonUnitContent {
  /** 原版 zh 表 id，立绘文件 zt_s{id}.webp */
  id: number
  name: string
  /** 原版 zh[3]：召唤物自动行动使用的技能。 */
  baseAttackId: number
  /** 六维系数（生命/物攻/物防/法防/法攻/速度，%），乘施法者面板 */
  coeffs: readonly [number, number, number, number, number, number]
  durationMs: number
  route: 'external' | 'internal'
}

